	function get_full_link($row) {

		global $config;

		if( intval( $row['category'] ) and $config['seo_type'] == 2 ) {
			$full_link = $config['http_home_url'] . get_url( intval( $row['category'] ) ) . "/" . $row['id'] . "-" . $row['alt_name'] . "/";
		} else {
			$full_link = $config['http_home_url'] . $row['id'] . "-" . $row['alt_name'] . "/";
		}

		return $full_link;
	}


	function generate_episodes() {

		global $db, $config;

		$row = $db->super_query( "SELECT COUNT(*) as count FROM " . PREFIX . "_serials" );

        $this->limit = $row['count'];

		if ( $this->limit > $this->news_per_file ) {

			$pages_count = @ceil( $row['count'] / $this->news_per_file );

			$n = 0;

			for ($i =0; $i < $pages_count; $i++) {

				$n = $n+1;

				$this->get_episodes($n);

			}

		} else {

			$this->get_episodes();

		}
	}

	function generate_seasones() {

		global $db, $config;

		$db->super_query( "SELECT SQL_CALC_FOUND_ROWS id FROM " . PREFIX . "_serials GROUP BY news_id, season" );

		$row = $db->super_query("SELECT FOUND_ROWS() as count");

        $this->limit = $row['count'];

		if ( $this->limit > $this->news_per_file ) {

			$pages_count = @ceil( $row['count'] / $this->news_per_file );

			$n = 0;

			for ($i =0; $i < $pages_count; $i++) {

				$n = $n+1;

				$this->get_seasones($n);

			}


		} else {

			$this->get_seasones();

		}
	}



    function get_episodes( $page = false ) {

		global $db, $config;

		$this->priority = $this->news_priority;
		$this->changefreq = $this->news_changefreq;
		$prefix_page = '';

		if ( $page ) {

			if( $page != 1 ) $prefix_page = $page;

			$page = $page - 1;
			$page = $page * $this->news_per_file;
			$this->limit = " LIMIT {$page}, {$this->news_per_file}";

		} else {

			if( $this->limit < 1 ) $this->limit = false;

			if( $this->limit ) {

				$this->limit = " LIMIT 0," . $this->limit;

			} else {

				$this->limit = "";

			}
		}

		$this->db_result = $db->query("SELECT s.season, s.episode, p.id, p.title, p.date, p.category, p.alt_name FROM " . PREFIX . "_serials s LEFT JOIN " . PREFIX . "_post p ON(s.news_id=p.id)" . $this->limit );

		$this->sitemap->links("episodes_pages{$prefix_page}.xml", function($map) {

			global $db, $config;

			$k = 1;

			while ( $row = $db->get_row( $this->db_result ) ) {

				$date = time()-$k;

				$loc = $this->get_full_link($row);

				$loc .= $row['season'].'-season-'.$row['episode'].'-episode.html';

				$map->loc($loc)->freq($this->changefreq)->lastMod( date('c', $date ) )->priority( $this->priority );

				$k+=2;

			}

		});


	}


    function get_seasones( $page = false ) {

		global $db, $config;

		$this->priority = $this->news_priority;
		$this->changefreq = $this->news_changefreq;
		$prefix_page = '';

		if ( $page ) {

			if( $page != 1 ) $prefix_page = $page;

			$page = $page - 1;
			$page = $page * $this->news_per_file;
			$this->limit = " LIMIT {$page}, {$this->news_per_file}";

		} else {

			if( $this->limit < 1 ) $this->limit = false;

			if( $this->limit ) {

				$this->limit = " LIMIT 0," . $this->limit;

			} else {

				$this->limit = "";

			}
		}

		$this->db_result = $db->query("SELECT s.season, p.id, p.title, p.date, p.category, p.alt_name FROM " . PREFIX . "_serials s LEFT JOIN " . PREFIX . "_post p ON(s.news_id=p.id) GROUP BY s.news_id, s.season" . $this->limit );

		$this->sitemap->links("seasones_pages{$prefix_page}.xml", function($map) {

			global $db, $config;

			$k = 1;

			while ( $row = $db->get_row( $this->db_result ) ) {

				$date = time()-$k;

				$loc = $this->get_full_link($row);

				$loc .= $row['season'].'-season.html';

				$map->loc($loc)->freq($this->changefreq)->lastMod( date('c', $date ) )->priority( $this->priority );

				$k+=2;

			}

		});


	}
